<?php require_once __DIR__.'/bootstrap.php'; $q=trim((string)($_GET['q']??'')); if($q!==''){ $s=$pdo->prepare('SELECT * FROM products WHERE active=1 AND (title LIKE ? OR description LIKE ?) ORDER BY id DESC'); $like='%'.$q.'%'; $s->execute([$like,$like]); $products=$s->fetchAll(); } else $products=$pdo->query('SELECT * FROM products WHERE active=1 ORDER BY id DESC')->fetchAll(); page_start('Shop'); ?>
<section class="panel" style="margin-bottom:24px;background:linear-gradient(120deg,#101b3a,#254fe0);color:white"><p class="small" style="letter-spacing:.12em">CURATED FINDS · DELIVERED TO YOU</p><h1>Find something worth keeping.</h1><p>Shop products sourced through our CJ Dropshipping catalogue.</p><form method="get" class="row"><input name="q" value="<?=e($q)?>" placeholder="Search products…" style="background:white"><button>Search</button></form></section>
<?php if(!$products): ?><div class="panel"><h2>No products yet</h2><p class="muted">The store owner can import product variants from the admin dashboard after configuring CJ API access.</p></div><?php else: ?><div class="grid"><?php foreach($products as $p): ?><article class="card"><?php if($p['image_url']): ?><img src="<?=e($p['image_url'])?>" alt="<?=e($p['title'])?>" loading="lazy"><?php else: ?><div style="height:190px;display:grid;place-items:center;background:#f1f3f7;border-radius:10px">Product image</div><?php endif ?><h3><?=e($p['title'])?></h3><p class="muted"><?=e(mb_strimwidth((string)$p['description'],0,120,'…'))?></p><div class="price"><?=money($p['price'])?></div><form method="post" action="cart.php"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="add"><input type="hidden" name="product_id" value="<?=(int)$p['id']?>"><button style="width:100%">Add to cart</button></form></article><?php endforeach ?></div><?php endif; page_end(); ?>
